/* Destination edition. Published routes with local notes, favourites and travel tools. */
(()=>{'use strict';
const G=JSON.parse(document.getElementById('guide-data').textContent),P=Object.fromEntries(G.places.map(p=>[p.id,p]));
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='travel-magazine-v4-bali-8d-v4-test';let storageOK=true,undo=null,toastTimer,dbPromise,blobURLs=[],travelReturnFocus=null,travelReturnScroll=0;
const fresh=()=>({version:1,day:0,modes:{},custom:{},saved:[],checks:[],notes:{},members:['我'],expenses:[],repayments:[],budget:G.edition.budget});
function validState(x){return x&&MemberAvatars.valid(x.memberAvatars,x.members||[])&&x.version===1&&Number.isInteger(x.day)&&x.day>=0&&x.day<G.days.length&&Array.isArray(x.saved)&&x.saved.every(k=>P[k])&&Array.isArray(x.checks)&&x.checks.every(k=>typeof k==='string'&&k.length<=80&&/^(c\d+|prep-[a-z0-9-]+)$/.test(k))&&Array.isArray(x.members)&&x.members.length>0&&x.members.length<31&&new Set(x.members).size===x.members.length&&x.members.every(m=>typeof m==='string'&&m.length>0&&m.length<25)&&x.notes&&Object.values(x.notes).every(v=>typeof v==='string')&&x.modes&&Object.values(x.modes).every(m=>['standard','gentle','rain'].includes(m))&&x.custom&&Object.values(x.custom).every(v=>Array.isArray(v)&&v.every(id=>P[id]))&&Array.isArray(x.expenses)&&x.expenses.every(e=>typeof e.id==='string'&&typeof e.title==='string'&&Number.isFinite(e.amount)&&e.amount>0&&e.amount<=99999999&&(e.currency===undefined||/^[A-Z]{3}$/.test(e.currency))&&Number.isInteger(Math.round(e.amount*100))&&Math.abs(e.amount*10**JournalLedger.digits(e.currency||G.edition.currency)-Math.round(e.amount*10**JournalLedger.digits(e.currency||G.edition.currency)))<1e-6&&x.members.includes(e.payer)&&Array.isArray(e.split)&&e.split.length>0&&new Set(e.split).size===e.split.length&&e.split.every(n=>x.members.includes(n)))&&(x.repayments===undefined||(Array.isArray(x.repayments)&&x.repayments.every(r=>typeof r.id==='string'&&x.members.includes(r.from)&&x.members.includes(r.to)&&r.from!==r.to&&Number.isFinite(r.amount)&&r.amount>0&&r.amount<=99999999&&(r.currency===undefined||/^[A-Z]{3}$/.test(r.currency))&&Math.abs(r.amount*10**JournalLedger.digits(r.currency||G.edition.currency)-Math.round(r.amount*10**JournalLedger.digits(r.currency||G.edition.currency)))<1e-6)))&&Number.isFinite(x.budget)&&x.budget>=0}
let state=fresh();try{let raw=localStorage.getItem(KEY);if(raw){let parsed=JSON.parse(raw);if(validState(parsed))state=parsed}}catch(e){storageOK=false}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch(e){storageOK=false}$('#storage-status').textContent=storageOK?'已启用本机保存。更换浏览器、清理浏览数据或移动文件后，记录可能无法自动跟随；请导出备份。':'浏览器未允许持久保存，当前修改只在本次页面中有效；请导出备份。';return storageOK}
function openDialog(id){const d=$(id);if(d.classList.contains('travel-dialog')){const previous=document.querySelector('.travel-dialog[open]');d.dataset.arrival=previous?'switch':'enter';if(!previous){travelReturnFocus=document.activeElement;travelReturnScroll=scrollY;}if(previous&&previous!==d)previous.close();document.body.classList.add('travel-open')}if(!d.open)d.showModal();if(d.classList.contains('travel-dialog')&&d.dataset.arrival==='switch')d.querySelector('.tool-section-nav [aria-current]').focus({preventScroll:true});if(id==='#menu-dialog')document.querySelectorAll('#menu-open,[data-open-menu]').forEach(b=>b.setAttribute('aria-expanded','true'))}
function freeTime(p){return ['spa','coffee','beachrest'].includes(p.id)}
function map(p){const query=p.query||[p.local,p.area,G.edition.english].filter(Boolean).join(' ');if(G.edition.lang==='ko')return (state.notes.mapProvider==='apple'?'https://map.kakao.com/?q=':'https://map.naver.com/p/search/')+encodeURIComponent(query);if(freeTime(p))return '#tools';return (state.notes.mapProvider==='apple'?'https://maps.apple.com/?q=':'https://www.google.com/maps/search/?api=1&query=')+encodeURIComponent(query)}
function routeIds(day=state.day){return G.days[day].stops.map(s=>s[1])}
function routeMarkup(ids){return (window.guideMapMarkup?.(G.days[state.day].id,ids)||'')+'<p class="route-label">当前地点顺序 · 点名称打开在线地图</p><div class="route-strip">'+ids.map((id,i)=>freeTime(P[id])?`<span class="free-time">${i+1}. ${esc(P[id].name)} · 地点待定</span>`:`<a href="${esc(map(P[id]))}" target="_blank" rel="noopener">${i+1}. ${esc(P[id].name)}</a>`).join('')+'</div>'}
function currentInfo(){return {d:G.days[state.day],ids:routeIds()}}
function dayContinuation(){const next=G.days[state.day+1];return `<nav class="day-continuation" aria-label="继续阅读行程"><div><p>第 ${state.day+1} 天 · ${state.day+1} / ${G.days.length}</p><strong>${next?'接着看：'+esc(next.area):G.days.length+' 天路线到这里结束'}</strong></div>${next?`<button data-day="${state.day+1}" data-next-day>下一天 · 第 ${state.day+2} 天 →</button>`:'<a href="#food">接着选餐厅与当地美食 →</a>'}</nav>`}
function renderDay(){requestAnimationFrame(()=>{const n=document.getElementById('day-tabs'),b=n?.querySelector('[aria-pressed=true]');if(n&&b&&n.scrollWidth>n.clientWidth){n.scrollLeft+=b.getBoundingClientRect().left-n.getBoundingClientRect().left-(n.clientWidth-b.clientWidth)/2}});
 const {d,ids}=currentInfo(),timings=daySchedule();
 $('#day-tabs').style.setProperty('--day-position',String(state.day));
 $('#day-tabs').innerHTML=G.days.map((d,i)=>`<button data-day="${i}" aria-pressed="${i===state.day}"><span>${String(i+1).padStart(2,'0')}</span><small>${esc(d.area)}</small></button>`).join('');
 $('#day-view').innerHTML=`<header class="day-opening"><div class="day-folio" aria-hidden="true"><span>DAY</span><b>${String(state.day+1).padStart(2,'0')}</b><small>OF ${G.days.length}</small></div><div class="day-opening-copy"><p class="kicker">DAY ${String(state.day+1).padStart(2,'0')} / ${esc(d.area)}</p><h3 class="day-title">${d.title.split("，").map((part,i,all)=>`<span>${esc(part)}${i<all.length-1?"，":""}</span>`).join("")}</h3><p>${esc(d.lead)}</p></div><div class="day-facts"><span><b>${timings[0].time}</b>建议开始</span><span><b>${timings[timings.length-1].endTime}</b>预计结束</span><span><b>${ids.length}</b>个停留点</span><button data-open-pocket>随身查看 ↗</button></div></header><div class="day-layout"><div>${schedulePanel()}<details class="route-fold"><summary>当天路线地图<span>展开地图 ＋</span></summary>${routeMarkup(ids)}</details><div class="timeline">${ids.map((id,i)=>{const p=P[id],slot=timings[i];return `<article class="timeline-item"><div class="stop-stamp"><span class="stop-order">STOP ${String(i+1).padStart(2,'0')}</span><time>${slot.time}</time><span class="time-caption"><span>至 ${slot.endTime}</span><span>${slot.duration} 分钟</span></span></div><div class="stop-body">${slot.transfer?`<p class="stop-transfer">↳ ${esc(slot.transfer.label)}${/\d+\s*分钟/.test(slot.transfer.label)?'':' · 预留 '+slot.transfer.minutes+' 分钟'}</p>`:''}<header class="stop-heading"><h4>${esc(p.name)}</h4><span>${esc(p.kind)}</span></header><div class="stop-detail">${placePhoto(p,true)}<div class="stop-reading"><p class="stop-description">${esc(p.desc)}</p><p class="stop-advice"><span>现场提示</span>${esc(p.tip)}</p></div></div>${slot.guard&&slot.guard!==p.tip?`<p class="time-guard">${esc(slot.guard)}</p>`:""}<div class="links"><button data-place="${id}">详情</button><a href="${esc(map(p))}" target="_blank" rel="noopener">导航 ↗</a><button data-attach-stop="${id}">＋ 票据</button></div><div class="asset-shortcuts" data-asset-shortcuts="${id}"></div></div></article>`}).join('')}</div></div><aside class="day-aside"><p class="kicker">DAY NOTES / 当天速查</p><article><h4>交通衔接</h4><p>${esc(d.move)}</p></article><article><h4>天气与取舍</h4><p>${esc(d.guard)}</p></article><article><h4>花费预留</h4><p>${esc(d.budget)}</p><p class="small muted">按 1 人预留，具体口径见上文；实际支出以当天为准。</p></article><details class="day-photo-note"><summary>摄影提示 ＋</summary><p>${esc(d.photo)}</p></details></aside></div>`;
 $('#day-view').insertAdjacentHTML('beforeend',dayContinuation());
 $('#week-overview').innerHTML=G.days.map((d,i)=>`<div class="week-row"><strong>DAY ${i+1}</strong><div><b>${esc(d.title)}</b><p>${routeIds(i).map(id=>esc(P[id].name)).join(' → ')}</p></div></div>`).join('');
 currentToolsRefresh();if($('#pocket-dialog').open)renderPocket();renderJourneyOverview();
}
function placePhoto(p,compact=false){const f=G.placePhotos?.[p.id];return f?`<figure class="place-photo ${compact?'compact':''}"><img src="${esc(f.src)}" alt="${esc(f.caption)}" loading="lazy" data-zoom><figcaption>${esc(f.caption)}${f.page?` · <a href="${esc(f.page)}" target="_blank" rel="noopener">来源 ↗</a>`:''}</figcaption></figure>`:''}
const directoryAreas=[['all','全部地点',G.places.map(p=>p.id)],...Array.from(new Set(G.places.map(p=>p.area))).map((a,i)=>['area'+i,a,G.places.filter(p=>p.area===a).map(p=>p.id)])];
let directoryArea='all',directoryPage=1,directoryPrinting=false;const pageSize=6;
function renderDirectory(reset=false){
 if(reset)directoryPage=1;
 const q=$('#place-search').value.trim().toLocaleLowerCase(),kind=$('#kind-filter').value,saved=$('#saved-filter').getAttribute('aria-pressed')==='true';
 const area=directoryAreas.find(a=>a[0]===directoryArea)||directoryAreas[0];
 const rows=G.places.filter(p=>area[2].includes(p.id)&&(!q||[p.name,p.local,p.area,p.kind,p.desc,p.tip].join(' ').toLocaleLowerCase().includes(q))&&(!kind||p.kind===kind)&&(!saved||state.saved.includes(p.id)));
 const pages=Math.max(1,Math.ceil(rows.length/pageSize));directoryPage=Math.min(directoryPage,pages);
 const start=directoryPrinting?0:(directoryPage-1)*pageSize,shown=directoryPrinting?rows:rows.slice(start,start+pageSize);
 $('#directory-areas').innerHTML=directoryAreas.map(([id,title,ids])=>`<button data-directory-area="${id}" aria-pressed="${directoryArea===id}"><span>${title}</span><small>${ids.length}</small></button>`).join('');
 $('#result-count').textContent=rows.length?`${area[1]} · 共 ${rows.length} 处 · 当前 ${start+1}–${start+shown.length}`:'没有匹配的地点';
 $('[data-directory-reset]').hidden=!(q||kind||saved||directoryArea!=='all');
 $('#place-results').innerHTML=shown.length?shown.map((p,cardIndex)=>{
  const photo=G.placePhotos?.[p.id],days=G.days.flatMap((d,i)=>d.stops.some(s=>s[1]===p.id)?[i+1]:[]);
  const ordinal=String(G.places.findIndex(place=>place.id===p.id)+1).padStart(2,'0');
  const tone=['tower','momochi','nakasu'].includes(p.id)?'water':['ohori','castle','artmuseum','dazaifu','kyuhaku'].includes(p.id)?'garden':'street';
  const tag=days.length?'D'+days.join(' · D'):'备选地点';
  return `<article class="address-card${!photo?' address-text-only':''}" data-directory-id="${p.id}" data-tone="${tone}">${photo?`<figure class="directory-photo"><button data-place="${p.id}" aria-label="查看${esc(p.name)}详情">${photo?`<img src="${esc(photo.src)}" alt="${esc(photo.caption)}" loading="lazy" decoding="async">`:'<span>地点照片</span>'}</button>${photo?.page?`<a class="directory-credit" href="${esc(photo.page)}" target="_blank" rel="noopener" aria-label="${esc(p.name)}的照片来源">摄影来源 ↗</a>`:''}<span class="directory-day">${tag}</span></figure>`:``}<div class="address-copy"><div class="address-folio"><span aria-hidden="true">${ordinal}</span><small>${esc(G.edition.english)} / ADDRESS</small></div><p class="directory-meta">${esc(p.area)}<span>${esc(p.kind)}</span></p><h3><button data-place="${p.id}">${esc(p.name)}</button></h3><p class="directory-local" lang="${esc(G.edition.lang)}">${esc(p.local)}</p><p class="directory-description">${esc(p.desc)}</p><p class="directory-duration"><span>建议停留</span>${esc(p.duration)}</p></div><footer class="directory-actions"><button class="directory-detail" data-place="${p.id}">查看详情 ↗</button><a href="${esc(map(p))}" target="_blank" rel="noopener">导航 ↗</a><button class="save-button" data-save="${p.id}" aria-pressed="${state.saved.includes(p.id)}">${state.saved.includes(p.id)?'已收藏':'收藏 ＋'}</button></footer><div class="asset-shortcuts" data-asset-shortcuts="${p.id}"></div></article>`;
 }).join(''):'<div class="directory-empty"><h3>换一个查找范围</h3><p>可以清除筛选，或试试地名或类别等名称。</p><button data-directory-reset>查看全部地点 ↗</button></div>';
 $('#directory-pages').innerHTML=pages>1?`<button data-directory-page="${directoryPage-1}" ${directoryPage===1?'disabled':''}>上一页</button><div>${Array.from({length:pages},(_,i)=>`<button data-directory-page="${i+1}" ${directoryPage===i+1?'aria-current="page"':''} aria-label="第 ${i+1} 页">${i+1}</button>`).join('')}</div><button data-directory-page="${directoryPage+1}" ${directoryPage===pages?'disabled':''}>下一页</button>`:'';
 refreshAssetButtons();
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.directoryArea!==undefined){directoryArea=b.dataset.directoryArea;renderDirectory(true);$(`[data-directory-area="${directoryArea}"]`).focus({preventScroll:true})}
 if(b.hasAttribute('data-directory-reset')){directoryArea='all';$('#place-search').value='';$('#kind-filter').value='';$('#saved-filter').setAttribute('aria-pressed','false');renderDirectory(true);$('#place-search').focus({preventScroll:true})}
 if(b.dataset.directoryPage!==undefined&&!b.disabled){directoryPage=Number(b.dataset.directoryPage);renderDirectory();$('#result-count').scrollIntoView({behavior:document.documentElement.dataset.motion==='off'?'auto':'smooth',block:'start'});$('#result-count').focus({preventScroll:true})}
});
addEventListener('beforeprint',()=>{directoryPrinting=true;renderDirectory()});
addEventListener('afterprint',()=>{directoryPrinting=false;renderDirectory()});

function showPlace(id){const p=P[id];if(!p)return;$('#place-detail').dataset.id=id;$('#place-detail').innerHTML=`${placePhoto(p)}<p class="detail-kicker">${esc(p.area)} / ${esc(p.kind)}</p><h2 id="place-heading">${esc(p.name)}</h2><p class="detail-local" lang="${esc(G.edition.lang)}">${esc(p.local)}</p><p>${esc(p.desc)}</p><div class="detail-info"><p><strong>位置与到达</strong><br>${esc(p.where)}</p><p><strong>建议停留</strong><br>${esc(p.duration)}</p></div><div class="detail-tip"><strong>现场怎么用</strong><p>${esc(p.tip)}</p></div><p class="small muted">未列出的营业日、票价与场次，请在出发前打开来源确认。资料按条目来源核对；不是实时营业状态。</p><div class="detail-actions">${freeTime(p)?'<span>自由安排 · 请先选定场所</span>':`<a href="${esc(map(p))}" target="_blank" rel="noopener">地图导航 ↗</a>`}<a href="${esc(p.url)}" target="_blank" rel="noopener">官方 / 旅游来源 ↗</a><button class="save-button" data-save="${id}" aria-pressed="${state.saved.includes(id)}">${state.saved.includes(id)?'已收藏':'收藏'}</button></div>`;openDialog('#place-dialog');attachmentPanel(id)}
function savePlace(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();renderDirectory();$$(`[data-save="${id}"]`).forEach(b=>{b.textContent=state.saved.includes(id)?'已收藏':'收藏';b.setAttribute('aria-pressed',state.saved.includes(id))});toast(state.saved.includes(id)?'已加入收藏':'已移出收藏')}
function daySchedule(){return TravelSchedule.plan(G.days[state.day])}
function schedulePanel(){const d=G.days[state.day];return `<section class="schedule-panel"><div class="schedule-heading"><h4>按时间往下看</h4><span>建议时刻 · 非预约时间</span></div><p class="small">${d.scheduleNote||'以下为建议时刻，实际以预约与当天交通为准。'}</p><details class="period-fold"><summary>早、中、晚怎么安排 ＋</summary><div class="period-notes">${d.periods.map((t,i)=>`<p><strong>${['上午','下午','晚间'][i]}</strong>${esc(t)}</p>`).join('')}</div></details></section>`}
function xhs(p){return 'https://www.xiaohongshu.com/search_result?keyword='+encodeURIComponent(p.local+' '+G.edition.city)}
function photoAndShopping(d){return `<details class="pocket-reading"><summary>今天怎么买 ＋</summary>${(d.shopping.length?d.shopping:['今天未安排专门采购。需要补给或临时购物时，先确认剩余时间和店铺营业。']).map(p=>`<p>${esc(p)}</p>`).join('')}</details><div class="pocket-reading"><button data-tool="photos">查看今天的出片建议 ↗</button></div>`}
function renderPocket(){
 const {d,ids}=currentInfo(),slots=daySchedule();
 syncToolDays();
 $('#pocket-content').innerHTML=`
 <header class="pocket-day-intro"><div class="pocket-folio" aria-hidden="true"><span>DAY</span><b>${String(state.day+1).padStart(2,'0')}</b></div><div><p class="kicker">${esc(d.area)} / ${ids.length} 个停留点</p><h3>${d.title.split("，").map((part,i,all)=>`<span>${esc(part)}${i<all.length-1?"，":""}</span>`).join("")}</h3><p class="pocket-hours"><span>${slots[0].time} — ${slots.at(-1).endTime}</span>建议时段</p></div></header>
 ${TravelReference.quicklinks()}
 <div class="pocket-layout"><aside class="pocket-aside">
 <details class="pocket-map route-fold" ${matchMedia('(min-width: 851px)').matches?'open':''}><summary><span>当天路线</span><span class="fold-label">地图与站点 ＋</span></summary>${routeMarkup(ids)}<div class="provider-row"><label>导航使用<select id="map-provider"><option value="google" ${state.notes.mapProvider!=='apple'?'selected':''}>${G.edition.lang==='ko'?'Naver 地图':'Google 地图'}</option><option value="apple" ${state.notes.mapProvider==='apple'?'selected':''}>${G.edition.lang==='ko'?'Kakao 地图':'Apple 地图'}</option></select></label></div></details>
 ${window.TravelAlternatives.render(d,{P,esc,map})}
 ${TravelReference.dining(d,{P,esc})}
 <details class="pocket-reading"><summary>交通与花费 ＋</summary><p>${esc(d.lead)}</p><p>${esc(d.move)}</p><p>${esc(d.budget)}</p></details>
 </aside><div class="pocket-route"><div class="pocket-route-label"><span>ON THE WAY</span><span>按时间出发</span></div>
 ${ids.map((id,i)=>{const t=slots[i],p=P[id];return `<article class="pocket-stop"><div class="pocket-stamp"><span>STOP ${String(i+1).padStart(2,'0')}</span><time>${t.time}<span class="pocket-end">–${t.endTime}</span><span>${t.duration} 分钟</span></time></div><div class="pocket-stop-body"><header><h4>${esc(p.name)}</h4><span>${esc(p.kind)}</span></header><div class="pocket-place-reading"><p>${esc(p.desc)}</p>${p.walk?`<p>${esc(p.walk)}</p>`:""}<p class="small">${esc(p.tip)}</p></div>${t.guard&&t.guard.trim()!==p.tip.trim()?`<p class="pocket-time-guard"><span>行程提示</span>${esc(t.guard)}</p>`:''}<div class="pocket-stop-actions"><a class="pocket-navigate" href="${esc(map(p))}" target="_blank" rel="noopener">导航 ↗</a><button data-place="${id}">地点详情</button></div><details class="pocket-stop-more"><summary>票据与参考</summary><div><button data-attach-stop="${id}">＋ 票据</button><a href="${esc(xhs(p))}" target="_blank" rel="noopener">小红书 ↗</a></div></details><div class="asset-shortcuts" data-asset-shortcuts="${id}"></div>${slots[i+1]?.transfer?`<p class="schedule-transfer">↳ ${esc(slots[i+1].transfer.label)}${/\d+\s*分钟/.test(slots[i+1].transfer.label)?'':' · 预留 '+slots[i+1].transfer.minutes+' 分钟'}</p>`:''}</div></article>`}).join('')}
 <section class="pocket-notebook"><p class="kicker">DAY NOTES / 当天手记</p>${photoAndShopping(d)}<label>当天备注<textarea data-day-note="${esc(d.id)}" rows="3" placeholder="预约时间、集合点，或临时想记下的事…">${esc(state.notes[d.id]||'')}</textarea></label><div class="pocket-note-actions"><button data-tool="notes">打开旅途笔记 ↗</button><button id="pocket-directory">去地点库查找 ↗</button></div></section></div></div>`;
 refreshAssetButtons();
}
document.addEventListener('change',e=>{const t=e.target;if(t.id==='map-provider'){state.notes.mapProvider=t.value;persist();renderDay();renderPocket()}if(t.dataset.reservation){state.notes['reservation:'+t.dataset.reservation]=t.checked?'done':'';persist();t.closest('label').querySelector('span').textContent=t.checked?'已处理':'待处理'}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.attachStop){showPlace(b.dataset.attachStop);$('#place-detail .attachment-panel')?.scrollIntoView({behavior:document.documentElement.dataset.motion==='off'?'auto':'smooth'})}});

function checkCount(){const ids=new Set($$('[data-check]').map(e=>e.dataset.check)),done=[...ids].filter(id=>state.checks.includes(id)).length;$$('[data-check-count],#check-count').forEach(e=>e.textContent=`已完成 ${done} / ${ids.size} 项准备`)}
function syncInputs(){$$('[data-reservation]').forEach(t=>{t.checked=state.notes['reservation:'+t.dataset.reservation]==='done';t.closest('label').querySelector('span').textContent=t.checked?'已处理':'待处理'});$$('[data-note]').forEach(el=>el.value=state.notes[el.dataset.note]||'');$$('[data-check]').forEach(el=>el.checked=state.checks.includes(el.dataset.check));window.TravelReference?.syncFields();checkCount()}



const yen=n=>G.edition.currencySymbol+Math.round(n).toLocaleString('en-US');
function ledgerContext(){return {state,G,persist,toast,hasUndo:()=>!!undo,memberHasUndo:name=>!!undo&&(undo.payer===name||undo.split.includes(name)),saveMembers(next){const previous={members:state.members,notes:state.notes,memberAvatars:state.memberAvatars};Object.assign(state,next);persist();if(!storageOK){Object.assign(state,previous);return false}return true},saveDemo(next){const previous={members:state.members,expenses:state.expenses,repayments:state.repayments,memberAvatars:state.memberAvatars,notes:state.notes};Object.assign(state,next);persist();if(!storageOK){Object.assign(state,previous);return false}return true},saveAvatars(next){const previous=state.memberAvatars;state.memberAvatars=next;persist();if(!storageOK){state.memberAvatars=previous;return false}return true}}}
function renderLedger(){MagazineLedger.render(ledgerContext())}

function openTool(type){const id={ledger:'#ledger-dialog',files:'#files-dialog',photos:'#photos-dialog',notes:'#notes-dialog'}[type];if(!id)return;syncToolDays();if(type==='ledger')renderLedger();if(type==='files')renderFiles();if(type==='photos')renderReferences();if(type==='notes')renderTravelNotes();openDialog(id)}
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(KEY+'-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return dbPromise}
async function filesAll(){const d=await db();return new Promise((res,rej)=>{const q=d.transaction('files').objectStore('files').getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}
async function fileMutation(mode,value){const d=await db();return new Promise((res,rej)=>{const t=d.transaction('files','readwrite');const s=t.objectStore('files');mode==='put'?s.put(value):s.delete(value);t.oncomplete=()=>{refreshAssetButtons();res()};t.onerror=()=>rej(t.error)})}
async function renderFiles(){try{blobURLs.forEach(URL.revokeObjectURL);blobURLs=[];const allFiles=await filesAll(),fs=state.notes.fileScope==='day'?allFiles.filter(f=>f.day===G.days[state.day].id):allFiles;$('#file-status').textContent=`${state.notes.fileScope==='day'?'当前日期':'全部日期'} · ${fs.length} 个文件`;
 $('#file-list').innerHTML=fs.length?fs.map(f=>{const url=URL.createObjectURL(f.blob);blobURLs.push(url);return `<div class="file-row">${f.type.startsWith('image/')?`<img src="${url}" alt="${esc(f.name)}">`:`<span>${f.type==='text/plain'?'链接':'PDF'}</span>`}<div><a href="${url}" download="${esc(f.name)}">${esc(f.name)} ↓</a><small>${Math.ceil(f.blob.size/1024)} KB · ${esc(f.day?('第'+(G.days.findIndex(d=>d.id===f.day)+1)+'天'):'未指定日期')}${f.purpose==='reference'?' · 摄影参考':''}${f.place&&P[f.place]?' · '+esc(P[f.place].name):''}</small><button data-file-open="${esc(f.id)}">预览／打开</button><button data-rename-asset="${esc(f.id)}">改名</button></div><button data-delete-file="${esc(f.id)}">移除</button></div>`}).join(''):'<p class="empty">还没有添加文件。保存机票、预约截图或旅途照片。</p>'}catch(e){$('#file-status').textContent='当前无法读取本机附件。请保留原文件；文字笔记仍可导出。'}}
function fileAsData(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(blob)})}
async function backup(){
 try{
  let files=[],attachmentsComplete=true;const exported=[];
  try{files=await filesAll()}catch(e){attachmentsComplete=false}
  for(const f of files){try{exported.push({id:f.id,name:f.name,type:f.type,place:f.place||'',day:f.day||'',purpose:f.purpose||'',data:await fileAsData(f.blob)})}catch(e){attachmentsComplete=false}}
  const payload={format:G.edition.backupFormat||G.edition.slug+'-backup',version:1,state,files:exported,attachmentsComplete};
  if(!attachmentsComplete)payload.backupNote='文字记录已备份，部分或全部附件未能读取；请保留原文件。';
  const u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=G.edition.city+'手册-'+(attachmentsComplete?'本机备份':'附件不完整备份')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);
  toast(attachmentsComplete?'已导出文字记录与本机附件':'文字已导出，附件未完整导出；请保留原文件');
 }catch(e){toast('未能生成备份，请重试并检查浏览器下载与存储权限')}
}

document.addEventListener('click',e=>{const b=e.target.closest('button,a,[data-zoom]');if(!b)return;
 if(b.hasAttribute('data-close')){b.closest('dialog').close();return}
 if(b.dataset.place){showPlace(b.dataset.place);return}
 if(b.dataset.save){savePlace(b.dataset.save);return}
 if(b.dataset.day!==undefined){const dialog=b.closest('.travel-dialog'),focusInside=dialog?.open;state.day=Number(b.dataset.day);persist();renderDay();if(focusInside){dialog.querySelector('.tool-day-nav [aria-pressed="true"]').focus({preventScroll:true});dialog.querySelector('.travel-body').scrollTop=0}return}
 if(b.dataset.tool){openTool(b.dataset.tool);return}
 if(b.dataset.reference){TravelReference.open(b.dataset.reference,{d:G.days[state.day],openDialog,syncInputs},b.dataset.restaurant);return}
 if(b.hasAttribute('data-clear-checks')){state.checks=[];persist();syncInputs();toast('清单已清空');return}
 if(b.dataset.deleteExpense){undo=state.expenses.find(x=>x.id===b.dataset.deleteExpense);state.expenses=state.expenses.filter(x=>x.id!==b.dataset.deleteExpense);persist();renderLedger();return}
 if(b.dataset.deleteFile){fileMutation('delete',b.dataset.deleteFile).then(()=>{renderFiles();toast('本机副本已移除，原文件未删除')}).catch(()=>toast('移除失败'));return}
 if(b.hasAttribute('data-zoom')){$('#photo-big').src=b.src;$('#photo-big').alt=b.alt;$('#photo-caption').textContent=b.alt;openDialog('#photo-dialog');return}
 if(b.dataset.jp){TravelReference.showPhrase(b,{lang:G.edition.lang,esc,openDialog});return}
 if(b.closest('#menu-dialog')&&b.matches('a[href^="#"]'))$('#menu-dialog').close();
 if(b.hasAttribute('data-open-menu')){openDialog('#menu-dialog');return}
 switch(b.id){case'menu-open':openDialog('#menu-dialog');break;case'pocket-open':renderPocket();openDialog('#pocket-dialog');break;case'pocket-directory':travelReturnScroll=null;travelReturnFocus=$('#place-search');$('#pocket-dialog').close();location.hash='directory';$('#place-search').focus({preventScroll:true});break;case'saved-filter':b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');renderDirectory(true);break;case'checks-clear':state.checks=[];persist();syncInputs();toast('清单已清空');break;case'export-data':backup();break;case'undo-expense':if(undo){state.expenses.push(undo);undo=null;persist();renderLedger()}break}
});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.note)updateNote(t.dataset.note,t.value,t);if(t.hasAttribute('data-day-note'))updateNote(t.dataset.dayNote||G.days[state.day].id,t.value,t);if(t.id==='place-search')renderDirectory(true)});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.check){state.checks=t.checked?[...new Set([...state.checks,t.dataset.check])]:state.checks.filter(x=>x!==t.dataset.check);const saved=persist();$$('[data-check]').forEach(el=>el.checked=state.checks.includes(el.dataset.check));checkCount();if(!saved)toast('勾选只保留在本页；本机保存失败，关闭前请导出备份。')}if(t.id==='kind-filter')renderDirectory(true);if(t.id==='trip-budget'){const n=MagazineLedger.parseAmount(t.value);if(Number.isFinite(n)&&n>=0&&n<=999999999){state.budget=Math.round(n*10**JournalLedger.digits(G.edition.currency))/10**JournalLedger.digits(G.edition.currency);persist();renderLedger()}}});
$('#member-form').addEventListener('submit',e=>{e.preventDefault();const f=e.target,m=f.member.value.trim();if(!m||m.length>24)return;if(state.members.includes(m)){if(MemberAvatars.inactive(state).includes(m)){if(!MemberAvatars.restore(m,ledgerContext())){toast('保存失败，请重试');return}f.reset();renderLedger();toast('已恢复成员分摊');return}toast('成员已存在');return}if(state.members.length>=30){toast('最多支持 30 位成员');return}if(!ledgerContext().saveMembers({members:[...state.members,m]})){toast('保存失败，成员未添加');return}f.reset();renderLedger();toast('成员已添加')});
$('#expense-form').addEventListener('submit',e=>MagazineLedger.submit(ledgerContext(),e));
$('#file-input').addEventListener('change',async e=>{for(const f of e.target.files){if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(f.type)||f.size>20*1024*1024){toast('跳过不支持或超过 20MB 的文件：'+f.name);continue}try{await fileMutation('put',{id:crypto.randomUUID(),name:f.name,type:f.type,day:G.days[state.day].id,blob:f})}catch(err){$('#file-status').textContent='保存附件失败，可能是浏览器存储空间不足。';return}}e.target.value='';renderFiles()});
$('#import-data').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>200*1024*1024)throw Error();const data=JSON.parse(await f.text());if(data.format!==(G.edition.backupFormat||G.edition.slug+'-backup')||!validState(data.state)||!Array.isArray(data.files))throw Error();for(const x of data.files){if(typeof x.id!=='string'||typeof x.name!=='string'||!['image/jpeg','image/png','image/webp','application/pdf','text/plain'].includes(x.type)||typeof x.data!=='string'||!x.data.startsWith('data:'+x.type+';base64,')||x.data.length>29*1024*1024)throw Error()}
 // Merge attachments; replace text state only after attachment validation completes.
 for(const x of data.files){const bytes=Uint8Array.from(atob(x.data.split(',')[1]),c=>c.charCodeAt(0));await fileMutation('put',{id:x.id,name:x.name,type:x.type,place:x.place||'',day:G.days.some(d=>d.id===x.day)?x.day:'',purpose:x.purpose==='reference'?'reference':'',blob:new Blob([bytes],{type:x.type})})}state=data.state;
persist();syncInputs();renderDay();renderDirectory();$('#file-scope').value=state.notes.fileScope||'all';$('#fx-rate').value=state.notes.fxRate||'';calc();toast(data.attachmentsComplete===false?'已恢复文字与备份内可用附件；这份备份的附件不完整':'已恢复备份中的收藏、账目、笔记与附件')}catch(err){toast('导入失败：请选择与当前旅程匹配的手册备份，或检查存储空间')}e.target.value=''});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));

async function attachmentPanel(id){const host=document.createElement('section');host.className='attachment-panel';host.innerHTML='<h3>这一站的票据与链接</h3><label>按钮名称<input class="attach-name" placeholder="如：晚餐预约 / 门票"></label><label>网页链接<input class="attach-url" type="text" placeholder="https:// 或含链接的小红书分享文字"></label><button class="attach-link">保存链接</button><label class="button">添加 PDF / 图片（20MB以内）<input class="attach-file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></label><div class="attach-list"></div>';$('#place-detail').append(host);
const refresh=async()=>{const fs=(await filesAll()).filter(f=>f.place===id),list=host.querySelector('.attach-list');list.replaceChildren();for(const f of fs){const row=document.createElement('p'),open=document.createElement('button');open.textContent=f.name+' ↗';open.onclick=()=>openAsset(f.id).catch(()=>toast('打开附件失败'));const rename=document.createElement('button');rename.textContent='编辑名称';rename.onclick=async()=>{const name=prompt('附件按钮名称',f.name);if(name?.trim()){await fileMutation('put',{...f,name:name.trim()});refresh()}};const del=document.createElement('button');del.textContent='删除';del.onclick=async()=>{if(confirm('删除此附件的本机副本？')){await fileMutation('delete',f.id);refresh()}};row.append(open,rename,del);list.append(row)}};
const save=async(blob,name)=>{await fileMutation('put',{id:crypto.randomUUID(),place:id,day:G.days[state.day].id,name:host.querySelector('.attach-name').value.trim()||name,type:blob.type,blob});await refresh()};host.querySelector('.attach-link').onclick=async()=>{const raw=host.querySelector('.attach-url').value.trim(),u=raw.match(/https?:\/\/[^\s]+/i)?.[0]||'';if(!/^https?:\/\//i.test(u)){toast('请输入 http 或 https 链接');return}await save(new Blob([u],{type:'text/plain'}),'网页链接')};host.querySelector('.attach-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024){toast('附件不能超过20MB');return}if(!['application/pdf','image/jpeg','image/png','image/webp'].includes(f.type))return;await save(f,f.name);e.target.value=''};refresh().catch(()=>toast('附件存储不可用，请保留原文件'))}
const fx=document.createElement('details');fx.className='fx-box';fx.innerHTML=`<summary>${esc(G.edition.currencyName)} → 人民币 · 汇率换算</summary><label>${esc(G.edition.currencyName)}金额<input id="fx-amount" type="text" inputmode="decimal" data-money-input value="1,000"></label><label>1 ${esc(G.edition.currency)} = CNY<input id="fx-rate" type="number" min="0" step="0.000001" placeholder="填写汇率或联网刷新"></label><button id="fx-refresh">刷新汇率</button><p id="fx-result" aria-live="polite"></p><small id="fx-status">参考换算，不改变${esc(G.edition.currencyName)}账本。</small>`;$('#ledger-totals').before(fx);const calc=()=>{const rate=Number($('#fx-rate').value),amt=MagazineLedger.parseAmount($('#fx-amount').value);$('#fx-result').textContent=rate>0&&amt>=0?'约 ¥'+(amt*rate).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' CNY':'请填写有效汇率';if(rate>0){state.notes.fxRate=String(rate);persist()}};$('#fx-rate').value=state.notes.fxRate||'';fx.addEventListener('input',calc);$('#fx-refresh').onclick=async()=>{try{$('#fx-status').textContent='正在请求汇率…';const r=await fetch('https://open.er-api.com/v6/latest/'+encodeURIComponent(G.edition.currency),{signal:AbortSignal.timeout(10000)});const x=await r.json();if(!r.ok||!(x.rates?.CNY>0))throw Error();$('#fx-rate').value=x.rates.CNY;calc();$('#fx-status').textContent='参考汇率更新：'+x.time_last_update_utc+' · ExchangeRate-API'}catch(e){$('#fx-status').textContent='联网刷新失败；保留原值，可手动填写。'}};calc();


let overviewDay='all';
function renderJourneyOverview(){const host=$('#journey-overview');if(!host)return;
const colors=['#8e4930','#315b4a','#235b7c','#83652c','#74435b','#345c60','#563f7b','#59612d'];
const selected=overviewDay==='all'?G.days:G.days.filter((d,i)=>String(i)===overviewDay);
const sourceMap=overviewDay==='all'?G.maps.overview:(G.maps[G.days[Number(overviewDay)].id]||G.maps.overview);const map=TravelMapLayout.normalize(sourceMap,G.places);const pins=Object.fromEntries(map.pins.map(p=>[p.id,p]));
const paths=selected.map(d=>{const i=G.days.indexOf(d),points=d.stops.map(s=>pins[s[1]]).filter(Boolean).map(p=>`${p.px},${p.py}`).join(' ');return `<polyline points="${points}" fill="none" stroke="${colors[i%8]}" stroke-width="6" stroke-linejoin="round" opacity=".85"/>`}).join('');
const used=[...new Set(selected.flatMap(d=>d.stops.map(s=>s[1])))].filter(id=>pins[id]);
const visibleNames=overviewDay==='all'?(G.edition.overviewIds||used):used;
const dots=visibleNames.filter(id=>pins[id]).map((id,i)=>{const p=pins[id],label=G.edition.overviewNames?.[id]||P[id].short||P[id].name;return `<g data-map-dot><circle cx="${p.px}" cy="${p.py}" r="14" fill="#fff9e8" stroke="#213b32" stroke-width="3"/><text data-map-number x="${p.px}" y="${p.py+5}" font-size="14" text-anchor="middle" fill="#172d26">${i+1}</text><text data-map-label data-px="${p.px}" data-py="${p.py}" x="${p.px+19}" y="${p.py-14}" font-size="21" font-weight="700" fill="#172d26" stroke="#fffdf5" stroke-width="6" paint-order="stroke">${esc(label)}</text></g>`}).join('');
host.innerHTML=`<div class="journey-heading"><div><p class="kicker">${G.days.length} DAYS / ONE MAP</p><h3>这几天怎么走</h3></div><div class="journey-filters"><button data-overview-day="all" aria-pressed="${overviewDay==='all'}">全部路线</button>${G.days.map((d,i)=>`<button data-overview-day="${i}" aria-pressed="${overviewDay===String(i)}">第${i+1}天</button>`).join('')}</div></div><div class="journey-layout"><div class="journey-map-column"><div class="journey-map-scroll" tabindex="0" aria-label="全程路线总图"><div class="journey-map-sheet" data-map-width="${map.projection.width}"><img src="${esc(map.src)}" alt="${esc(map.title)}" width="${map.projection.width}" height="${map.projection.height}"><svg viewBox="0 0 ${map.projection.width} ${map.projection.height}" role="img" aria-label="建议访问顺序">${paths}${dots}</svg></div></div><div class="journey-map-caption"><p>各色线表示每天的建议访问顺序，非实际道路。点上方日期可单独看一天；具体交通以下方时间表为准。</p><button data-overview-zoom aria-pressed="false">放大地图 ↗</button></div><p class="map-credit">底图：${esc(map.attribution||map.tileSource||'底图来源见地图说明')}。标签拥挤时仅显示编号，名称见路线列表。</p></div><div class="journey-days">${G.days.map((d,i)=>`<article style="--day-color:${colors[i%8]}" ${overviewDay!=='all'&&overviewDay!==String(i)?'hidden':''}><p class="journey-day-number">DAY ${String(i+1).padStart(2,'0')}</p><h4>${esc(d.title)}</h4><details><summary>查看途经地点 ＋</summary><ol>${d.stops.map(s=>`<li><button data-place="${s[1]}">${esc(P[s[1]].name)} ↗</button></li>`).join('')}</ol></details><button data-overview-detail="${i}">看第${i+1}天详细行程 ↓</button></article>`).join('')}</div></div>`}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.overviewDay!==undefined){overviewDay=b.dataset.overviewDay;renderJourneyOverview()}if(b.hasAttribute('data-overview-zoom')){const stage=$('.journey-map-sheet'),large=stage.classList.toggle('enlarged');stage.style.width=large?stage.dataset.mapWidth+'px':'';b.setAttribute('aria-pressed',String(large));b.textContent=large?'还原地图 ↙':'放大地图 ↗';TravelMapLayout.fit()}if(b.dataset.overviewDetail!==undefined){state.day=Number(b.dataset.overviewDetail);persist();renderDay();document.querySelector('#itinerary').scrollIntoView({behavior:'smooth'})}});

// Tool additions share the existing state, backup format and attachment store.
let assetCache=[],assetEpoch=0,referenceURLs=[],repaymentUndo=null;
function avatar(m){return `<span class="member-avatar" aria-hidden="true">${esc([...m][0]||'?')}</span>`}

function noteSaveStatus(){
 $$('[data-notes-status]').forEach(el=>el.textContent=storageOK?'已自动保存到本机':'本机保存不可用，请及时导出备份');
}
function updateNote(key,value,source){
 state.notes[key]=value;
 $$('[data-note],[data-day-note]').forEach(el=>{
  const otherKey=el.hasAttribute('data-day-note')?(el.dataset.dayNote||G.days[state.day].id):el.dataset.note;
  if(el!==source&&otherKey===key)el.value=value;
 });
 persist();noteSaveStatus();
}
function renderTravelNotes(){
 const d=G.days[state.day],host=$('#travel-notes-content');
 host.innerHTML=`<div class="travel-notes-heading"><p class="kicker">ON THE ROAD / 随身记录</p><p data-notes-status role="status"></p></div>
 <div class="travel-notes-grid">
  <section class="travel-note-panel trip-note-panel"><p class="note-scope">ALL DAYS / 全程共用</p><h3><label for="travel-journal">旅途笔记</label></h3><p id="journal-hint">切换日期不会改变这里的内容。</p><textarea id="travel-journal" data-note="journal" aria-describedby="journal-hint" rows="9" placeholder="想再来的地方、喜欢的餐厅，或路上发生的事……">${esc(state.notes.journal||'')}</textarea></section>
  <section class="travel-note-panel day-note-panel"><p class="note-scope">DAY ${String(state.day+1).padStart(2,'0')} / ${esc(d.area)}</p><h3><label for="travel-day-note">当天备注</label></h3><p id="day-note-hint">记录今天的预约、集合与临时安排。</p><textarea id="travel-day-note" data-day-note="${esc(d.id)}" aria-describedby="day-note-hint" rows="9" placeholder="预约时间、集合点，或今天想记下的事……">${esc(state.notes[d.id]||'')}</textarea></section>
 </div><p class="travel-notes-foot">笔记自动保存在当前浏览器；换设备前可到「随身工具」导出备份。</p>`;
 noteSaveStatus();
}

function toolDays(active){return `<div class="tool-context"><nav class="tool-day-nav" aria-label="选择旅行日">${G.days.map((d,i)=>`<button data-day="${i}" aria-label="第 ${i+1} 天" aria-pressed="${state.day===i}"><span>DAY</span> ${String(i+1).padStart(2,'0')}</button>`).join('')}</nav><nav class="tool-section-nav" aria-label="旅行工具"><button data-open-pocket ${active==='pocket'?'aria-current="page"':''}>当天行程</button><button data-tool="notes" ${active==='notes'?'aria-current="page"':''}>旅途笔记</button><button data-tool="photos" ${active==='photos'?'aria-current="page"':''}>摄影参考</button><button data-tool="ledger" ${active==='ledger'?'aria-current="page"':''}>记账结算</button></nav></div>`}
function syncToolDays(){for(const [id,kind] of [['pocket-dialog','pocket'],['ledger-dialog','ledger'],['files-dialog','files'],['photos-dialog','photos'],['notes-dialog','notes']]){const dialog=$('#'+id);if(!dialog)continue;let host=dialog.querySelector('.tool-context-host');if(!host){host=document.createElement('div');host.className='tool-context-host';dialog.querySelector('.dialog-head').after(host)}host.innerHTML=toolDays(kind)}requestAnimationFrame(()=>{
 const nav=document.querySelector('.travel-dialog[open] .tool-day-nav'),selected=nav?.querySelector('[aria-pressed="true"]');
 if(nav&&selected&&nav.scrollWidth>nav.clientWidth)nav.scrollLeft+=selected.getBoundingClientRect().left-nav.getBoundingClientRect().left-(nav.clientWidth-selected.clientWidth)/2;
 })}
function initTravelShells(){
 for(const id of ['pocket','ledger','files','photos','notes']){
  const dialog=$('#'+id+'-dialog'),head=dialog.querySelector('.dialog-head');dialog.classList.add('travel-dialog');
  const title=head.querySelector('h2'),brand=document.createElement('div');brand.className='travel-brand';brand.innerHTML='<span>PRIVATE JOURNAL</span><small>'+esc(G.edition.city)+' / '+esc(G.edition.span)+'</small>';head.prepend(brand);title.classList.add('travel-tool-title');
  head.querySelector('[data-close]').innerHTML='<span>返回杂志</span> <b aria-hidden="true">×</b>';
  const body=document.createElement('div');body.className='travel-body';Array.from(dialog.children).filter(el=>el!==head&&!el.classList.contains('tool-context-host')).forEach(el=>body.append(el));dialog.append(body);
  if(id==='files')body.insertAdjacentHTML('afterbegin','<header class="travel-files-heading"><p class="kicker">DOCUMENTS / 随身资料</p><h3>票据与附件</h3></header>');
  if(id==='ledger'){
   body.classList.add('ledger-layout');
   for(const [name,selector] of [['ledger-summary',':scope > p.small,.fx-box,#ledger-totals'],['ledger-entry','#member-form,#members-list,#expense-form'],['ledger-history','#expense-list,#settlement,#repayment-panel,#undo-expense']]){const group=document.createElement(name==='ledger-summary'?'aside':'section');group.className=name;body.querySelectorAll(selector).forEach(el=>group.append(el));body.append(group)}
   const explanation=body.querySelector('.ledger-summary > p.small');if(explanation)explanation.textContent=G.edition.currencyName+'记账，可选择同行成员分摊。';
   const membersFold=document.createElement('details');membersFold.className='ledger-member-fold';membersFold.innerHTML='<summary>同行成员与头像<small><span data-member-count>'+state.members.length+'</span> 人 · 管理</small></summary><p>新增成员不会自动参与之前的账目。</p>';
   body.querySelector('#expense-form').before(membersFold);membersFold.append(body.querySelector('#member-form'),body.querySelector('#members-list'));
  }
  dialog.addEventListener('close',()=>{if(!document.querySelector('.travel-dialog[open]')){document.body.classList.remove('travel-open');if(travelReturnFocus?.isConnected)travelReturnFocus.focus({preventScroll:true});requestAnimationFrame(()=>{if(Number.isFinite(travelReturnScroll))scrollTo({top:travelReturnScroll,behavior:'instant'});document.dispatchEvent(new Event('journal:day'))})}});
 }
}
function currentToolsRefresh(){syncToolDays();if($('#ledger-dialog').open)renderLedger();if($('#files-dialog').open)renderFiles();if($('#photos-dialog').open)renderReferences();if($('#notes-dialog').open)renderTravelNotes();refreshAssetButtons();document.dispatchEvent(new Event('journal:day'))}
function repaymentUI(result){
 const host=$('#repayment-panel');if(!host)return;
 const list=state.repayments||[];
 host.innerHTML=`<h3>已经还过的钱</h3><p>转账完成后在这里记一笔，结算建议会扣除已还金额。这里只记录，不执行转账，也不计入旅行花费。</p><form id="repayment-form"><div class="repayment-fields"><label>谁还款<select name="from">${state.members.map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('')}</select></label><label>还给谁<select name="to">${state.members.map((m,i)=>`<option value="${esc(m)}" ${i===1?'selected':''}>${esc(m)}</option>`).join('')}</select></label><label>金额（${esc(G.edition.currencyName)}）<input name="amount" type="number" min="1" max="99999999" step="1" required></label></div><button ${state.members.length<2?'disabled':''}>记录已还款</button><p id="repayment-status" role="status">${state.members.length<2?'先在上方添加同行成员。':''}</p></form><div class="repayment-list">${list.map(r=>`<article><span>${avatar(r.from)}${esc(r.from)} → ${avatar(r.to)}${esc(r.to)}</span><strong>${yen(r.amount)}</strong><button data-delete-repayment="${esc(r.id)}">删除记录</button></article>`).join('')||'<p class="small muted">暂无还款记录。</p>'}</div><button data-undo-repayment ${repaymentUndo?'':'hidden'}>撤销删除还款记录</button>`;
 $('#repayment-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target),from=String(data.get('from')),to=String(data.get('to')),amount=Number(data.get('amount'));if(from===to||!state.members.includes(from)||!state.members.includes(to)||!Number.isSafeInteger(amount)||amount<=0||amount>99999999){$('#repayment-status').textContent='请选择不同的还款人与收款人，填写正整数金额。';return}state.repayments??=[];state.repayments.push({id:crypto.randomUUID(),from,to,amount,date:new Date().toISOString()});const saved=persist();renderLedger();const message=saved?'已记录还款，旅行花费不变':'还款已记在本页，但未保存到本机；关闭前请导出备份。';if($('#repayment-status'))$('#repayment-status').textContent=message;toast(message)});
}
async function refreshAssetButtons(){const epoch=++assetEpoch;try{const all=await filesAll();const links=new Map();await Promise.all(all.filter(f=>f.type==='text/plain').map(async f=>{const u=await f.blob.text();if(/^https?:\/\//i.test(u))links.set(f.id,u)}));if(epoch!==assetEpoch)return;assetCache=all;$$('[data-asset-shortcuts]').forEach(host=>{host.replaceChildren();all.filter(f=>f.place===host.dataset.assetShortcuts).forEach(f=>{const b=document.createElement(links.has(f.id)?'a':'button');if(links.has(f.id)){b.href=links.get(f.id);b.target='_blank';b.rel='noopener'}else b.dataset.fileOpen=f.id;b.textContent=f.name+' ↗';b.title=f.name;host.append(b)})})}catch(e){/* The add action remains available if local storage is blocked. */}}
async function openAsset(id){
 const f=assetCache.find(x=>x.id===id)||(await filesAll()).find(x=>x.id===id);if(!f)return;
 if(f.type==='text/plain'){const u=await f.blob.text();if(!/^https?:\/\//i.test(u)){toast('链接格式无效');return}const dialog=document.createElement('dialog');dialog.className='attachment-preview';const close=document.createElement('button');close.textContent='关闭 ×';close.onclick=()=>dialog.close();const a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener';a.textContent='打开 '+f.name+' ↗';dialog.append(close,a);dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();return}
 const url=URL.createObjectURL(f.blob),dialog=document.createElement('dialog');dialog.className='attachment-preview';const head=document.createElement('div');head.className='dialog-head';const title=document.createElement('h2');title.textContent=f.name;const close=document.createElement('button');close.textContent='关闭 ×';close.onclick=()=>dialog.close();head.append(title,close);dialog.append(head);const el=document.createElement(f.type==='application/pdf'?'iframe':'img');el.src=url;el.title=f.name;if(el.tagName==='IMG')el.alt=f.name;dialog.append(el);dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);dialog.remove()},{once:true});document.body.append(dialog);dialog.showModal();
}
function initExtraTools(){
 const notes=document.createElement('dialog');notes.id='notes-dialog';notes.setAttribute('aria-labelledby','travel-notes-title');notes.innerHTML='<div class="dialog-head"><h2 id="travel-notes-title">旅途笔记</h2><button data-close>关闭 ×</button></div><div id="travel-notes-content"></div>';document.body.append(notes);
 const d=document.createElement('dialog');d.id='photos-dialog';d.setAttribute('aria-labelledby','photos-heading');d.innerHTML='<div class="dialog-head"><h2 id="photos-heading">摄影参考</h2><button data-close>关闭 ×</button></div><div id="reference-content"></div>';document.body.append(d);
 const r=document.createElement('section');r.id='repayment-panel';$('#settlement').after(r);
 const nav=document.createElement('nav');nav.className='reading-actions';nav.setAttribute('aria-label','手册快捷入口');nav.innerHTML='<button class="reading-position" data-open-menu aria-label="当前章节，打开全书目录" aria-controls="menu-dialog" aria-expanded="false"><span class="position-caption">正在阅读</span><strong id="reading-location">封面</strong><svg class="nav-icon" viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg></button><div class="reading-shortcuts"><a href="#orientation" data-reading-group="city"><span class="nav-long">城市与街区</span><span class="nav-short">城市</span></a><a href="#itinerary" data-reading-group="days"><span class="nav-long">每日行程</span><span class="nav-short">行程</span></a><a href="#directory" data-reading-group="places"><span class="nav-long">地点查找</span><span class="nav-short">地点</span></a><a href="#fieldnotes" data-reading-group="tips"><span class="nav-long">实用贴士</span><span class="nav-short">贴士</span></a></div>';$('.topbar').after(nav);const progress=document.createElement('div');progress.className='reading-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);
 $('#menu-dialog').addEventListener('close',()=>document.querySelectorAll('#menu-open,[data-open-menu]').forEach(b=>b.setAttribute('aria-expanded','false')));
 const filter=document.createElement('label');filter.className='file-scope';filter.innerHTML='查看附件<select id="file-scope"><option value="all">全部日期</option><option value="day">当前日期</option></select>';$('#file-status').before(filter);$('#file-scope').value=state.notes.fileScope||'all';$('#file-scope').onchange=e=>{state.notes.fileScope=e.target.value;persist();renderFiles()};syncToolDays();initTravelShells();
 d.addEventListener('close',()=>{photoEpoch++;referenceURLs.forEach(URL.revokeObjectURL);referenceURLs=[]});
}
let photoEpoch=0;
function photoPlanMarkup(d){
 const shots=d.photoPlan||[];
 if(!shots.length)return `<div class="photo-shot-list">${[...new Set(d.shooting||[d.photo])].filter(Boolean).map((t,i)=>`<article class="photo-shot"><p class="shot-time">建议 ${i+1}</p><p>${esc(t)}</p></article>`).join('')}</div>`;
 return `<div class="photo-shot-list">${shots.map(s=>`<article class="photo-shot"><p class="shot-time">${esc(s.time)}</p><h4>${esc(s.title)}</h4><dl>${[['光线',s.light],['构图',s.composition],['人像',s.portrait],['设置',s.settings]].filter(x=>x[1]).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${s.placeId&&P[s.placeId]?`<button data-place="${esc(s.placeId)}">${esc(P[s.placeId].name)} · 地点详情 ↗</button>`:''}</article>`).join('')}</div>`;
}
async function renderReferences(){
 const epoch=++photoEpoch,day=G.days[state.day].id,host=$('#reference-content'),plan=`<header class="photo-plan-heading"><h3>今天怎么拍</h3><span>第 ${state.day+1} 天</span></header>${photoPlanMarkup(G.days[state.day])}`;host.innerHTML=plan+'<p role="status">正在读取本机参考照片…</p>';
 try{const fs=(await filesAll()).filter(f=>f.purpose==='reference'&&f.day===day);if(epoch!==photoEpoch)return;referenceURLs.forEach(URL.revokeObjectURL);referenceURLs=[];
 host.innerHTML=`${plan}<section class="reference-library"><h3>我的参考照片</h3><div class="reference-upload-row"><label class="file-picker"><span aria-hidden="true">＋</span> 添加照片<input id="reference-upload" aria-label="添加参考照片" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p id="reference-status" role="status">${fs.length} 张 · JPG / PNG / WebP · 每张上限20MB</p></div><div class="reference-grid">${fs.map(f=>{const url=URL.createObjectURL(f.blob);referenceURLs.push(url);return `<article><button data-file-open="${esc(f.id)}" class="reference-image" aria-label="放大${esc(f.name)}"><img src="${url}" alt="${esc(f.name)}"></button><p>${esc(f.name)}</p><div><button data-rename-asset="${esc(f.id)}">改名</button><button data-delete-asset="${esc(f.id)}">删除</button></div></article>`}).join('')||''}</div><button data-clear-references ${fs.length?'':'hidden'}>清空这一天的参考照片</button><details class="storage-note"><summary>照片保存与备份</summary><p>照片保存在当前浏览器；换设备前到随身工具导出备份。</p></details></section>`;
 $('#reference-upload').onchange=async e=>{const selected=[...e.target.files];e.target.disabled=true;try{for(const f of selected){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>20*1024*1024){toast('跳过不支持或超过20MB的图片');continue}await fileMutation('put',{id:crypto.randomUUID(),name:f.name,type:f.type,blob:f,day,purpose:'reference'})}if($('#photos-dialog').open)await renderReferences()}catch(e){$('#reference-status').textContent='保存失败，请保留原照片并检查浏览器空间。'}finally{e.target.disabled=false}};
 }catch(e){if(epoch===photoEpoch)host.innerHTML=plan+'<p role="status">当前无法读取本机参考照片；上方拍摄建议仍可使用。请保留原照片。</p>'}
}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-open-pocket')){renderPocket();openDialog('#pocket-dialog')}
 if(b.dataset.deleteRepayment){const r=state.repayments.find(r=>r.id===b.dataset.deleteRepayment);if(r){repaymentUndo=r;state.repayments=state.repayments.filter(x=>x.id!==r.id);persist();renderLedger();toast('已删除还款记录，可撤销')}}
 if(b.hasAttribute('data-undo-repayment')&&repaymentUndo){state.repayments.push(repaymentUndo);repaymentUndo=null;persist();renderLedger()}
 try{
 if(b.dataset.fileOpen)await openAsset(b.dataset.fileOpen);
 if(b.dataset.renameAsset){const f=(await filesAll()).find(x=>x.id===b.dataset.renameAsset);if(!f)return;const name=prompt('照片／附件名称',f.name);if(name?.trim())await fileMutation('put',{...f,name:name.trim().slice(0,120)});if($('#photos-dialog').open)renderReferences();if($('#files-dialog').open)renderFiles()}
 if(b.dataset.deleteAsset&&confirm('删除这个本机副本？原文件不受影响。')){await fileMutation('delete',b.dataset.deleteAsset);if($('#photos-dialog').open)renderReferences();if($('#files-dialog').open)renderFiles()}
 if(b.hasAttribute('data-clear-references')){const day=G.days[state.day].id;if(!confirm('清空第'+(state.day+1)+'天的参考照片？其他日期和票据保留。'))return;for(const f of (await filesAll()).filter(f=>f.purpose==='reference'&&f.day===day))await fileMutation('delete',f.id);if($('#photos-dialog').open)renderReferences()}
 }catch(e){toast('操作未完成，请检查浏览器存储权限或可用空间')}
});

function initFieldNotes(){
 const nav=$('.tip-topic-nav'),tabs=$$('[data-tip-topic]'),panels=$$('.tip-panel');if(!nav)return;
 nav.setAttribute('role','tablist');nav.setAttribute('aria-label','实用贴士主题');
 const vertical=matchMedia('(min-width: 851px)');
 const setOrientation=()=>nav.setAttribute('aria-orientation',vertical.matches?'vertical':'horizontal');setOrientation();vertical.addEventListener('change',setOrientation);
 function select(id,focus=false){
  if(!tabs.some(t=>t.dataset.tipTopic===id))id=tabs[0].dataset.tipTopic;
  tabs.forEach(t=>{const active=t.dataset.tipTopic===id;t.setAttribute('role','tab');t.setAttribute('aria-controls','tip-'+t.dataset.tipTopic);t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;if(active&&focus)t.focus({preventScroll:true})});
  panels.forEach(p=>{p.setAttribute('role','tabpanel');p.hidden=p.id!=='tip-'+id});
  document.dispatchEvent(new CustomEvent('journal:topic',{detail:{id}}));
 }
 nav.addEventListener('click',e=>{const a=e.target.closest('[data-tip-topic]');if(!a)return;e.preventDefault();select(a.dataset.tipTopic);history.replaceState(null,'','#tip-'+a.dataset.tipTopic)});
 nav.addEventListener('keydown',e=>{const current=tabs.indexOf(e.target);if(current<0)return;const previous=vertical.matches?'ArrowUp':'ArrowLeft',next=vertical.matches?'ArrowDown':'ArrowRight';let index=current;if(e.key===previous)index=(current+tabs.length-1)%tabs.length;else if(e.key===next)index=(current+1)%tabs.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=tabs.length-1;else return;e.preventDefault();select(tabs[index].dataset.tipTopic,true)});
 const fromHash=()=>{if(location.hash.startsWith('#tip-'))select(location.hash.slice(5))};addEventListener('hashchange',fromHash);
 select(location.hash.startsWith('#tip-')?location.hash.slice(5):tabs[0].dataset.tipTopic);
}
initFieldNotes();
initExtraTools();
persist();syncInputs();renderDay();renderDirectory();
})();
